import './App.css';
import Gallery from './components/Gallery';
import React, {useState, useEffect} from 'react'
import { useDataLayerValue } from './DataLayer'
import * as Realm from "realm-web";
import { data } from 'autoprefixer';
const appId = "keenan-kgkzv"; // e.g. myapp-abcde
const appConfig = {
  id: appId,
  timeout: 10000,
};






function App() {

  const [loading, setLoading] = useState(false);
  const [{data},dispatch] = useDataLayerValue();

  async function pusher (){

     const app = new Realm.App(appConfig);
     const credentials = Realm.Credentials.serverApiKey("9icRBkm9bOSqAG9dqw7xsOmUSgZom07esC78XDIdSm4Gl9u3BXdJK93hRqOIeWgT");
     const user = await app.logIn(credentials);
     const mongodb = app.currentUser.mongoClient("mongodb-atlas");
     const artwork = mongodb.db("keenan").collection("artwork");
     const data = await artwork.find({});
     console.log(data);
     dispatch({
      type: "SET_DATA",
      data: data,
    });
     setLoading(true)
    return;

  }

  useEffect( async() => {
     const app = new Realm.App(appConfig);
     const credentials = Realm.Credentials.serverApiKey("9icRBkm9bOSqAG9dqw7xsOmUSgZom07esC78XDIdSm4Gl9u3BXdJK93hRqOIeWgT");
     const user = await app.logIn(credentials);
     const mongodb = app.currentUser.mongoClient("mongodb-atlas");
     const artwork = mongodb.db("keenan").collection("artwork");
     const data = await artwork.find({});
     console.log(data);
     dispatch({
      type: "SET_DATA",
      data: data,
    });
     setLoading(true)
    console.log(data);
  }, [])

  return (
    !loading ? 
    <div>
      loading
    </div> 
    :
    <div className={"flex flex-wrap content-center justify-center h-screen w-screen"}>
      <div className="block ">
        <div className={"text-center text-4xl m-8 font-mono italic bold"}>Keenan Cassidy</div>
        <Gallery data={data} />
      </div>
    </div>
  );
}

export default App;
